class Solution {
public:
    std::vector<long long> mergeAdjacent(std::vector<int>& nums) {
        std::vector<long long> st;
        for (int x : nums) {
            long long cur = x;
            while (!st.empty() && st.back() == cur) {
                cur += st.back();
                st.pop_back();
            }
            st.push_back(cur);
        }
        return st;
    }
};

import java.util.*;

class Solution {
    public long[] mergeAdjacent(int[] nums) {
        List<Long> st = new ArrayList<>();
        for (int x : nums) {
            long cur = x;
            while (!st.isEmpty() && st.get(st.size() - 1) == cur) {
                cur += st.remove(st.size() - 1);
            }
            st.add(cur);
        }
        long[] res = new long[st.size()];
        for (int i = 0; i < st.size(); i++) res[i] = st.get(i);
        return res;
    }
}

